/* ---------- डायग्राम S4 : ऊष्मा का रास्ता (Thermal Path) ---------- */
/* window.SVdiagThermal -> app.js का alias "SVthermal" */
window.SVdiagThermal = function SVdiagThermal() {
  var s = '<svg viewBox="0 0 900 560" xmlns="http://www.w3.org/2000/svg">' + SVdefs('svth', '#f97316');
  s += SVtxt(450, 26, 'CPU की गर्मी का सफ़र — सिलिकॉन से हवा तक (हर पड़ाव पर अड़चन)', '#94a3c4', 13.5);
  var steps = [
    ['CPU Die (सिलिकॉन)', 'यहीं गर्मी बनती है — 100°C तक पहुँच सकती है', '#ef4444'],
    ['IHS (हीट स्प्रेडर)', 'सोल्डर या पेस्ट से जुड़ा धातु का ढक्कन', '#f97316'],
    ['TIM (थर्मल पेस्ट)', 'IHS और कूलर के बीच की पतली परत — यही हम बदलते हैं', '#facc15'],
    ['कूलर बेस + हीटपाइप', 'ताँबे का बेस, हीटपाइप से ऊपर फ़िन तक', '#22d3ee'],
    ['हीटसिंक फ़िन + हवा', 'फ़िन से हवा को गर्मी — यहाँ धूल सबसे बड़ी दुश्मन', '#22c55e']
  ];
  steps.forEach(function (r, i) {
    var y = 52 + i * 84;
    s += SVbox(60, y, 500, 68, r[0], r[1], '#101827', r[2], 14);
    if (i < steps.length - 1) s += SVline(310, y + 68, 310, y + 84, '', '#4b5f7d', 'svth');
  });
  s += SVtxt(310, 492, 'गर्मी का रास्ता एक शृंखला है — सबसे कमज़ोर कड़ी पूरे सिस्टम को गर्म कर देती है', '#8fa6c4', 11.5);
  /* दाएँ : थ्रॉटलिंग ग्राफ़ */
  s += SVbox(600, 52, 270, 44, 'तापमान बढ़ने पर क्या होता है', 'थर्मल थ्रॉटलिंग', '#221a10', '#f59e0b', 12.5);
  var pts = [[625, 250], [665, 232], [705, 208], [745, 170], [785, 116], [825, 92]];
  var path = pts.map(function (p, i) { return (i ? 'L' : 'M') + p[0] + ',' + p[1]; }).join(' ');
  s += '<polyline points="' + pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ') + '" fill="none" stroke="#f97316" stroke-width="3"/>';
  s += SVline(615, 258, 858, 258, '', '#4b5f7d');
  s += SVline(615, 258, 615, 86, '', '#4b5f7d');
  s += SVtxt(600, 274, '40°C', '#8fa6c4', 10.5, 'start');
  s += SVtxt(700, 274, '70°C', '#8fa6c4', 10.5, 'start');
  s += SVtxt(800, 274, '90°C+', '#ef4444', 10.5, 'start');
  s += SVtxt(868, 250, 'घड़ी', '#8fa6c4', 10.5, 'end');
  s += SVtxt(600, 292, 'घड़ी (GHz)', '#8fa6c4', 10, 'start');
  s += SVtxt(650, 130, 'थ्रॉटलिंग शुरू', '#f59e0b', 11.5, 'start');
  s += SVtxt(650, 150, '(गर्मी के कारण CPU ख़ुद धीमा)', '#8fa6c4', 10.5, 'start');
  s += SVsmall(600, 310, 270, 52, '100°C = Tjmax — यहाँ CPU पूरी तरह धीमा होकर 800MHz पर आ जाता है, और लंबे समय में चिप की उम्र घटती है।', '#2a1517', '#ef4444', 11.5);
  s += SVsmall(600, 374, 270, 66, 'मोटी पेस्ट की परत = ज़्यादा रेज़िस्टेंस = तापमान 5–10°C ऊपर। सही मात्रा: दाने के आकार जितनी, IHS के बीच में।', '#122036', '#38bdf8', 11.5);
  return s + '</svg>';
};

/* ---------- डायग्राम S5 : 24-pin ATX पिनआउट व मल्टीमीटर ---------- */
/* window.SVdiagMultimeter -> app.js का alias "SVmultimeter" */
window.SVdiagMultimeter = function SVdiagMultimeter() {
  var s = '<svg viewBox="0 0 900 540" xmlns="http://www.w3.org/2000/svg">' + SVdefs('svmm', '#38bdf8');
  s += SVtxt(450, 26, 'SMPS की जाँच — 24-pin ATX पिनआउट और मल्टीमीटर की रीडिंग', '#94a3c4', 13.5);
  /* कनेक्टर */
  s += SVtxt(60, 62, '24-pin ATX कनेक्टर (लॉक ऊपर)', '#cfe3ff', 12.5, 'start', 700);
  var top = [['1', '+3.3V', 'नारंगी'], ['2', '+3.3V', 'नारंगी'], ['3', 'COM', 'काला'], ['4', '+5V', 'लाल'], ['5', 'COM', 'काला'], ['6', '+5V', 'लाल'],
             ['7', 'COM', 'काला'], ['8', 'PWR_OK', 'स्लेटी'], ['9', '+5VSB', 'बैंगनी'], ['10', '+12V', 'पीला'], ['11', '+12V', 'पीला'], ['12', '+3.3V', 'नारंगी']];
  var bot = [['13', '+3.3V', 'नारंगी'], ['14', '-12V', 'नीला'], ['15', 'COM', 'काला'], ['16', 'PS_ON#', 'हरा'], ['17', 'COM', 'काला'], ['18', 'COM', 'काला'],
             ['19', 'COM', 'काला'], ['20', '-5V (पुराना)', 'सफ़ेद'], ['21', '+5V', 'लाल'], ['22', '+5V', 'लाल'], ['23', '+5V', 'लाल'], ['24', 'COM', 'काला']];
  function cell(x, y, t, sub, fill, stroke) {
    return '<g><rect x="' + x + '" y="' + y + '" width="62" height="52" rx="6" fill="' + fill + '" stroke="' + stroke + '" stroke-width="1.6"/>' +
      '<text x="' + (x + 31) + '" y="' + (y + 22) + '" text-anchor="middle" fill="#e8eefc" font-size="12" font-weight="700" font-family="' + SVM + '">' + t + '</text>' +
      '<text x="' + (x + 31) + '" y="' + (y + 39) + '" text-anchor="middle" fill="#cfe3ff" font-size="9.5" font-family="' + SVF + '">' + sub + '</text></g>';
  }
  top.forEach(function (p, i) { s += cell(60 + i * 66, 74, p[0], p[1], p[1] === 'COM' ? '#1a1a1a' : '#101827', p[1] === 'COM' ? '#6b7280' : '#3b82f6'); });
  bot.forEach(function (p, i) { s += cell(60 + i * 66, 132, p[0], p[1], '#101827', p[1] === 'PS_ON#' ? '#22c55e' : (p[1] === 'COM' ? '#6b7280' : '#3b82f6')); });
  s += SVtxt(60, 208, 'मुख्य पिन: 16 (PS_ON#, हरा) को 15 (COM, काला) से जोड़ने पर SMPS बिना मदरबोर्ड चालू हो जाता है — इसे “पेपरक्लिप ट्रिक” कहते हैं।', '#7dd3fc', 11.5, 'start', 500);
  s += SVtxt(60, 228, '9 (+5VSB) हमेशा ज़िंदा रहता है — यही वो रेल है जिससे फ्रंट पैनल का बटन SMPS को जगाता है।', '#facc15', 11.5, 'start', 500);
  /* रीडिंग तालिका */
  s += SVtxt(60, 262, 'मल्टीमीटर रीडिंग (डायल: DC वोल्ट, 20V रेंज)', '#cfe3ff', 12.5, 'start', 700);
  var rl = [['+12V', 'पीला', '11.40 – 12.60 V'], ['+5V', 'लाल', '4.75 – 5.25 V'], ['+3.3V', 'नारंगी', '3.14 – 3.47 V'],
            ['+5VSB', 'बैंगनी', '4.75 – 5.25 V'], ['-12V', 'नीला', '-10.80 – -13.20 V'], ['PWR_OK', 'स्लेटी', '3.0 – 6.0 V (सिग्नल)']];
  rl.forEach(function (r, i) {
    var y = 276 + i * 30;
    s += SVsmall(60, y, 130, 25, r[0], '#101827', '#38bdf8', 11.5);
    s += SVsmall(198, y, 110, 25, r[1], '#101827', '#3b82f6', 11 );
    s += SVsmall(316, y, 200, 25, r[2], '#12261a', '#22c55e', 11);
  });
  s += SVtxt(60, 470, 'टॉलरेंस: ATX मानक ±5% (कुछ नई सीरीज़ में ±3%) — इससे बाहर मिलने पर SMPS बदल दें।', '#f59e0b', 11.5, 'start', 600);
  /* मल्टीमीटर */
  s += SVbox(600, 74, 270, 76, 'मल्टीमीटर सेटिंग', 'V⎓ (DC वोल्ट) · रेंज 20V या ऑटो', '#101827', '#facc15', 13);
  var mm = ['लाल प्रोब (+) → जाँचने वाला पिन', 'काला प्रोब (−) → कोई भी COM (काला तार)', 'डायल DC वोल्ट पर, AC पर नहीं', 'निरंतरता (Continuity) → तार/फ़्यूज़ जाँचने के लिए', 'हाथ एक ही प्रोब पर (एक-हाथ नियम)'];
  mm.forEach(function (t, i) { s += SVtxt(606, 178 + i * 26, '• ' + t, '#b6c7de', 11, 'start', 500); });
  s += SVtxt(606, 330, 'जाँच का क्रम', '#cfe3ff', 12.5, 'start', 700);
  var ord = [['1', 'पावर केबल निकालकर SMPS को मदरबोर्ड से अलग कीजिए'], ['2', 'पेपरक्लिप/clip से PS_ON को COM से जोड़िए'],
             ['3', 'SMPS का पावर केबल लगाइए (पंखा घूमेगा)'], ['4', '24-pin में हर रेल नापिए'], ['5', 'टॉलरेंस से बाहर हो तो बदलिए']];
  ord.forEach(function (t, i) {
    var y = 346 + i * 30;
    s += SVtxt(610, y + 14, t[0], '#38bdf8', 12, 'middle', 700);
    s += SVtxt(628, y + 14, t[1], '#b6c7de', 10.8, 'start', 500);
  });
  s += SVsmall(600, 500, 270, 34, 'चेतावनी: कभी भी SMPS को मदरबोर्ड से जुड़ा रखकर प्रोब न लगाएँ, और अंदर हाथ न डालें।', '#2a1517', '#ef4444', 11);
  return s + '</svg>';
};

/* ---------- डायग्राम S6 : उन्नयन का असर व बॉटलनेक ---------- */
/* window.SVdiagUpgrade -> app.js का alias "SVupgrade" */
window.SVdiagUpgrade = function SVdiagUpgrade() {
  var s = '<svg viewBox="0 0 900 480" xmlns="http://www.w3.org/2000/svg">' + SVdefs('svup', '#22d3ee');
  s += SVtxt(450, 26, 'किस उन्नयन से कितना फ़ायदा? — पैसे का सबसे बड़ा असर कहाँ', '#94a3c4', 13.5);
  var up = [
    ['SSD (HDD → SSD)', '95%', 'बूट 3–4× तेज़, विंडोज़ तुरंत खुले', '#22c55e'],
    ['RAM (4GB → 8/16GB)', '70%', 'मल्टी-टैब, ब्राउज़र, MS Office आराम से', '#22d3ee'],
    ['GPU (ऑनबोर्ड → कार्ड)', '60%', 'गेम, वीडियो एडिटिंग, 3D काम', '#a78bfa'],
    ['CPU (same socket)', '40%', 'रेंडरिंग/कंपाइल तेज़, पर बोर्ड-सीमा', '#f59e0b'],
    ['मदरबोर्ड + CPU साथ', '25%', 'तभी जब सॉकेट/रैम पुरानी हो चुकी हो', '#f472b6'],
    ['कूलर (स्टॉक → टावर)', '20%', 'शांत + तापमान कम + थ्रॉटल बंद', '#38bdf8'],
    ['केस + फैन', '15%', 'थोड़ा ठंडा, कम आवाज़', '#8fa6c4'],
    ['RGB/सजावट', '0%', 'सुंदरता — स्पीड नहीं', '#6b7280']
  ];
  up.forEach(function (r, i) {
    var y = 50 + i * 48;
    s += SVtxt(30, y + 26, r[0], '#cfe3ff', 12.5, 'start', 600);
    s += '<rect x="250" y="' + (y + 8) + '" width="380" height="28" rx="8" fill="#0d1524" stroke="#2b3a52" stroke-width="1.4"/>';
    var w = Math.round(parseFloat(r[1]) / 100 * 372);
    s += '<rect x="254" y="' + (y + 12) + '" width="' + w + '" height="20" rx="6" fill="' + r[3] + '" opacity="0.85"/>';
    s += SVtxt(644, y + 26, r[1], r[3], 12, 'start', 700);
    s += SVtxt(690, y + 26, r[2], '#9fb6d6', 11, 'start', 500);
  });
  s += SVbox(30, 434, 380, 34, 'बॉटलनेक (Bottleneck)', 'सबसे कमज़ोर पुर्ज़ा ही पूरे सिस्टम की रफ़्तार तय करता है', '#221a10', '#f59e0b', 12);
  s += SVbox(430, 434, 440, 34, 'लागत-लाभ का नियम', 'पहले वह बदलिए जो सबसे धीमा है, न कि जो सबसे “चमकदार” है', '#122036', '#38bdf8', 12);
  return s + '</svg>';
};

